unsafe fn UpdateNodes(
    num_bytes: size_t,
    block_start: size_t,
    pos: size_t,
    mut ringbuffer: *const uint8_t,
    ringbuffer_mask: size_t,
    mut params: *const BrotliEncoderParams,
    max_backward_limit: size_t,
    mut starting_dist_cache: *const c_int,
    num_matches: size_t,
    mut matches: *const BackwardMatch,
    mut model: *const ZopfliCostModel,
    mut queue: *mut StartPosQueue,
    mut nodes: *mut ZopfliNode,
) -> size_t {
    let stream_offset: size_t = (*params).stream_offset;
    let cur_ix: size_t = block_start.wrapping_add(pos);
    let cur_ix_masked: size_t = cur_ix & ringbuffer_mask;
    let max_distance: size_t = brotli_min_size_t(cur_ix, max_backward_limit) as size_t;
    let addon: *const CompoundDictionary = &raw const (*params).dictionary.compound;
    let gap: size_t = (*addon).total_size;
    let dictionary_start: size_t =
        brotli_min_size_t(cur_ix.wrapping_add(stream_offset), max_backward_limit) as size_t;
    let max_len: size_t = num_bytes.wrapping_sub(pos);
    let max_zopfli_len: size_t = MaxZopfliLen(params) as size_t;
    let max_iters: size_t = MaxZopfliCandidates(params) as size_t;
    let mut result: size_t = 0;

    EvaluateNode(
        block_start.wrapping_add(stream_offset),
        pos,
        max_backward_limit,
        gap,
        starting_dist_cache,
        model,
        queue,
        nodes,
    );

    let posdata0: *const PosData = StartPosQueueAt(queue, 0);
    let min_cost: c_float = (*posdata0).cost
        + ZopfliCostModelGetMinCostCmd(model)
        + ZopfliCostModelGetLiteralCosts(model, (*posdata0).pos, pos);
    let min_len: size_t = ComputeMinimumCopyLength(min_cost, nodes, num_bytes, pos);

    let queue_size: size_t = StartPosQueueSize(queue);
    let iters: size_t = if max_iters < queue_size { max_iters } else { queue_size };

    let cur_ptr = ringbuffer.wrapping_add(cur_ix_masked);
    let rb_end_ok = cur_ix_masked <= ringbuffer_mask;

    let mut k: size_t = 0;
    while k < iters {
        let posdata: *const PosData = StartPosQueueAt(queue, k);
        let start: size_t = (*posdata).pos;
        let insert_len: size_t = pos.wrapping_sub(start);
        let inscode: uint16_t = GetInsertLengthCode(insert_len) as uint16_t;
        let base_cost: c_float = (*posdata).costdiff
            + GetInsertExtra(inscode) as c_float
            + ZopfliCostModelGetLiteralCosts(model, 0, pos) as c_float;

        let mut best_len: size_t = min_len.wrapping_sub(1);
        let mut j: size_t = 0;

        while j < BROTLI_NUM_DISTANCE_SHORT_CODES as size_t && best_len < max_len {
            if !rb_end_ok || cur_ix_masked.wrapping_add(best_len) > ringbuffer_mask {
                break;
            }

            let idx: size_t = kDistanceCacheIndex[j as usize] as size_t;
            let backward: size_t =
                ((*posdata).distance_cache[idx as usize] + kDistanceCacheOffset[j as usize])
                    as size_t;

            if backward <= dictionary_start.wrapping_add(gap) {
                let continuation: uint8_t =
                    // SAFETY: cur_ix_masked + best_len <= ringbuffer_mask checked just above, and ringbuffer points to the ring buffer.
                    unsafe { *ringbuffer.add(cur_ix_masked.wrapping_add(best_len)) };
                let mut len: size_t = 0;
                let mut matched = false;

                if backward <= max_distance {
                    let mut prev_ix: size_t = cur_ix.wrapping_sub(backward);
                    if prev_ix < cur_ix {
                        prev_ix &= ringbuffer_mask;
                        if prev_ix.wrapping_add(best_len) <= ringbuffer_mask
                            && continuation as c_int
                                ==
                                // SAFETY: prev_ix + best_len <= ringbuffer_mask checked above, and ringbuffer points to the ring buffer.
                                unsafe { *ringbuffer.add(prev_ix.wrapping_add(best_len)) } as c_int
                        {
                            len = FindMatchLengthWithLimit(
                                // SAFETY: prev_ix is masked into the ring buffer range.
                                unsafe { ringbuffer.add(prev_ix) },
                                cur_ptr,
                                max_len,
                            );
                            matched = true;
                        }
                    }
                } else if backward > dictionary_start {
                    let mut d: size_t = 0;
                    let mut offset: size_t = dictionary_start
                        .wrapping_add(1)
                        .wrapping_add((*addon).total_size)
                        .wrapping_sub(1);
                    while offset
                        >= backward.wrapping_add((*addon).chunk_offsets[d.wrapping_add(1) as usize])
                    {
                        d = d.wrapping_add(1);
                    }
                    let source: *const uint8_t = (*addon).chunk_source[d as usize];
                    offset = offset
                        .wrapping_sub((*addon).chunk_offsets[d as usize])
                        .wrapping_sub(backward);
                    let mut limit: size_t = (*addon).chunk_offsets[d.wrapping_add(1) as usize]
                        .wrapping_sub((*addon).chunk_offsets[d as usize])
                        .wrapping_sub(offset);
                    if limit > max_len {
                        limit = max_len;
                    }
                    if best_len < limit
                        && continuation as c_int
                            ==
                            // SAFETY: best_len < limit and source points to the dictionary chunk, so offset + best_len is in-bounds for the compared prefix.
                            unsafe { *source.add(offset.wrapping_add(best_len)) } as c_int
                    {
                        len = FindMatchLengthWithLimit(
                            // SAFETY: offset is computed within the selected dictionary chunk bounds.
                            unsafe { source.add(offset) },
                            cur_ptr,
                            limit,
                        );
                        matched = true;
                    }
                }

                if matched {
                    let dist_cost: c_float =
                        base_cost + ZopfliCostModelGetDistanceCost(model, j) as c_float;
                    let mut l: size_t = best_len.wrapping_add(1);
                    while l <= len {
                        let copycode: uint16_t = GetCopyLengthCode(l) as uint16_t;
                        let cmdcode: uint16_t =
                            CombineLengthCodes(inscode, copycode, (j == 0) as c_int) as uint16_t;
                        let cost: c_float = (if (cmdcode as c_int) < 128 {
                            base_cost
                        } else {
                            dist_cost
                        }) + GetCopyExtra(copycode) as c_float
                            + ZopfliCostModelGetCommandCost(model, cmdcode) as c_float;
                        let node_ptr =
                            // SAFETY: pos + l indexes the nodes array exactly as in the original code.
                            unsafe { nodes.add(pos.wrapping_add(l)) };
                        if cost < (*node_ptr).u.cost {
                            UpdateZopfliNode(
                                nodes,
                                pos,
                                start,
                                l,
                                l,
                                backward,
                                j.wrapping_add(1),
                                cost,
                            );
                            result = brotli_max_size_t(result, l);
                        }
                        best_len = l;
                        l = l.wrapping_add(1);
                    }
                }
            }

            j = j.wrapping_add(1);
        }

        if k < 2 {
            let mut len_0: size_t = min_len;
            let mut m: size_t = 0;
            while m < num_matches {
                let mut match_0: BackwardMatch =
                    // SAFETY: m < num_matches and matches points to the match array.
                    unsafe { *matches.add(m) };
                let dist: size_t = match_0.distance as size_t;
                let is_dictionary_match: c_int = if dist > dictionary_start.wrapping_add(gap) {
                    BROTLI_TRUE
                } else {
                    BROTLI_FALSE
                };
                let dist_code: size_t = dist
                    .wrapping_add(BROTLI_NUM_DISTANCE_SHORT_CODES as size_t)
                    .wrapping_sub(1);
                let mut dist_symbol: uint16_t = 0;
                let mut distextra: uint32_t = 0;
                PrefixEncodeCopyDistance(
                    dist_code,
                    (*params).dist.num_direct_distance_codes as size_t,
                    (*params).dist.distance_postfix_bits as size_t,
                    &raw mut dist_symbol,
                    &raw mut distextra,
                );
                let distnumextra: uint32_t = (dist_symbol as c_int >> 10) as uint32_t;
                let dist_cost_0: c_float = base_cost
                    + distnumextra as c_float
                    + ZopfliCostModelGetDistanceCost(
                        model,
                        (dist_symbol as c_int & 0x3ff) as size_t,
                    );
                let max_match_len: size_t = BackwardMatchLength(&raw mut match_0);
                if len_0 < max_match_len
                    && (is_dictionary_match != 0 || max_match_len > max_zopfli_len)
                {
                    len_0 = max_match_len;
                }
                while len_0 <= max_match_len {
                    let len_code: size_t = if is_dictionary_match != 0 {
                        BackwardMatchLengthCode(&raw mut match_0) as size_t
                    } else {
                        len_0
                    };
                    let copycode_0: uint16_t = GetCopyLengthCode(len_code) as uint16_t;
                    let cmdcode_0: uint16_t =
                        CombineLengthCodes(inscode, copycode_0, 0) as uint16_t;
                    let cost_0: c_float = dist_cost_0
                        + GetCopyExtra(copycode_0) as c_float
                        + ZopfliCostModelGetCommandCost(model, cmdcode_0) as c_float;
                    let node_ptr =
                        // SAFETY: pos + len_0 indexes the nodes array exactly as in the original code.
                        unsafe { nodes.add(pos.wrapping_add(len_0)) };
                    if cost_0 < (*node_ptr).u.cost {
                        UpdateZopfliNode(nodes, pos, start, len_0, len_code, dist, 0, cost_0);
                        result = brotli_max_size_t(result, len_0);
                    }
                    len_0 = len_0.wrapping_add(1);
                }
                m = m.wrapping_add(1);
            }
        }

        k = k.wrapping_add(1);
    }

    result
}

